#include "ContentStore.h"
#include "LearningDeltaPublication.h"
#include <limits>
#include <algorithm>
namespace private_input::activity {namespace {
protocol::Ledger ledger(const Json&j){require(j.kind==Json::Kind::array&&j.items.size()<=64,"ledger size");protocol::Ledger result;for(const auto&r:j.items){auto key=std::make_tuple(parseId(r.at("group").str()),r.at("epoch").num(),parseId(r.at("sender").str()));require(result.emplace(key,protocol::Window{r.at("highest").num(),r.at("bitmap").num()}).second,"duplicate ledger");}return result;}
Json encodedLedger(const protocol::Ledger&rows){std::vector<Json>result;for(const auto&p:rows)result.push_back(Json::object({{"group",uuidText(std::get<0>(p.first))},{"epoch",std::get<1>(p.first)},{"sender",uuidText(std::get<2>(p.first))},{"highest",p.second.highest},{"bitmap",p.second.bitmap}}));return Json::array(result);}
std::string digest(const Json&j){auto e=decodeContentEnvelope(j);auto data=protocol::header(e);append(data,e.ciphertext);append(data,e.signature);auto hash=sha256(data);return base64(Data(hash.begin(),hash.end()));}
}
Json ContentStore::initial(){return Json::object({{"version",1},{"automaticOutgoing",Json::object()},{"compatibilityQueued",Json::object()},{"group",""},{"epoch",0},{"nextSequence",1},{"localLearningEnabled",true},{"learningEnabled",false},{"clipboardEnabled",false},{"archive",emptyLearning()},{"outgoing",Json::array()},{"ledger",Json::array()},{"receipts",Json::object()},{"texts",Json::array()},{"publishedDigest",""}});}
ContentStore::ContentStore(Json value,std::function<void(const Json&)>save):state(value.kind==Json::Kind::null?initial():value),persist(std::move(save)){if(!state.has("compatibilityQueued"))state["compatibilityQueued"]=Json::object();require(state.at("compatibilityQueued").fields.size()<=512,"compatibility receipt bounds");if(!state.has("automaticOutgoing"))state["automaticOutgoing"]=Json::object();require(state.at("automaticOutgoing").fields.size()<=2,"automatic outbox ownership bound");if(!state.has("localLearningEnabled"))state["localLearningEnabled"]=true;require(state.at("version").num()==1,"content store version");validateLearning(state.at("archive"));require(state.dump().size()<=8388608&&state.at("outgoing").items.size()<=2&&state.at("texts").items.size()<=20&&state.at("receipts").fields.size()<=512,"content state bound");(void)ledger(state.at("ledger"));}
void ContentStore::save(const Json&next){require(next.dump().size()<=8388608,"content store bound");persist(next);state=next;}
void ContentStore::configure(const Id&group,uint64_t epoch,bool learning,bool clipboard,bool preserveLocal){require(epoch>0,"content epoch");auto next=state;if(state.at("group").str()!=uuidText(group)){auto archive=next.at("archive");next=initial();if(preserveLocal)next["archive"]=archive;next["group"]=uuidText(group);}if(next.at("epoch").num()!=epoch){next["epoch"]=epoch;next["nextSequence"]=1;next["outgoing"]=Json::array();next["automaticOutgoing"]=Json::object();next["compatibilityQueued"]=Json::object();next["ledger"]=Json::array();next["receipts"]=Json::object();next["publishedDigest"]="";next.fields.erase("learningPublication");}if(!learning)next.fields.erase("learningPublication");next["learningEnabled"]=learning;next["clipboardEnabled"]=clipboard;auto out=next.at("outgoing");out.items.erase(std::remove_if(out.items.begin(),out.items.end(),[&](const Json&j){return j.at("domain").num()==1?!learning:!clipboard;}),out.items.end());next["outgoing"]=out;for(auto it=next["automaticOutgoing"].fields.begin();it!=next["automaticOutgoing"].fields.end();){if(std::none_of(out.items.begin(),out.items.end(),[&](const auto&wire){return wire.at("event").str()==it->first;}))it=next["automaticOutgoing"].fields.erase(it);else ++it;}if(!clipboard)next["texts"]=Json::array();if(next.dump()!=state.dump())save(next);}
void ContentStore::record(const std::string&reading,const std::string&text,const std::string&device){if(!state.at("localLearningEnabled").boolean())return;auto next=state;next["archive"]=recordLearning(state.at("archive"),reading,text,device);save(next);}
void ContentStore::enqueue(const Data&payload,uint8_t domain,const protocol::VerifiedMembership&membership,const GroupIdentity&identity,const Key&key,uint64_t now,bool automatic,const Id*fixedEvent,uint64_t fixedExpiry,const Json*learningPublication){require(!automatic||domain==2,"automatic content domain");require((domain==1?learningEnabled():clipboardEnabled())&&state.at("group").str()==uuidText(membership.anchor().group)&&state.at("epoch").num()==membership.statement().epoch,"sharing disabled or stale epoch");require(state.at("outgoing").items.size()<2&&now<=std::numeric_limits<uint64_t>::max()-604800,"content outbox full");auto next=state;auto sequence=next.at("nextSequence").num();require(sequence>0&&sequence<std::numeric_limits<uint64_t>::max(),"sequence exhausted");next["nextSequence"]=sequence+1;save(next);protocol::Envelope meta;meta.group=membership.anchor().group;meta.sender=identity.device;meta.event=fixedEvent?*fixedEvent:newId();meta.epoch=membership.statement().epoch;meta.sequence=sequence;meta.domain=domain;meta.issuedAt=now;meta.expiresAt=fixedEvent?fixedExpiry:now+(domain==1?604800:600);require(!fixedEvent||(fixedExpiry>now&&fixedExpiry-now<=600),"compatibility original expiry");auto envelope=protocol::sealOpaquePayload(payload,meta,key,identity.signingSeed,membership.trust(domain==1?protocol::MembershipDomain::learning:protocol::MembershipDomain::clipboard));next=state;next["outgoing"].items.push_back(encodeContentEnvelope(envelope));if(automatic)next["automaticOutgoing"][uuidText(meta.event)]=true;if(fixedEvent){auto&receipts=next["compatibilityQueued"];require(receipts.fields.size()<512,"compatibility receipt quota");auto hash=sha256(payload);receipts[uuidText(*fixedEvent)]=Json::object({{"digest",base64(Data(hash.begin(),hash.end()))},{"expiresAt",fixedExpiry}});}if(learningPublication){require(domain==1&&!automatic,"learning publication domain");next["learningPublication"]=learningPublication->at("checkpoint");next["publishedDigest"]=learningPublication->at("digest");}save(next);}
void ContentStore::changeWord(const std::string&reading,const std::string&text,const std::string&device,unsigned action){require(action>=5&&action<=7,"word action");auto next=state;auto archive=next.at("archive");auto rows=archive.at("entries");auto id=reading+char(31)+text;auto at=std::find_if(rows.items.begin(),rows.items.end(),[&](const auto&e){return e.at("reading").str()+char(31)+e.at("text").str()==id;});if(at==rows.items.end()){auto seed=recordLearning(emptyLearning(),reading,text,device);auto word=seed.at("entries").items[0];word["counts"]=Json::object();rows.items.push_back(word);at=rows.items.end()-1;}require(!at->at("deleted").boolean(),"deleted word");if(action==5){require(at->at("generation").num()<std::numeric_limits<uint64_t>::max(),"word generation exhausted");(*at)["generation"]=at->at("generation").num()+1;(*at)["counts"]=Json::object();}else{uint64_t sequence=0;for(const auto&e:rows.items)sequence=std::max(sequence,e.at("pinVersion").at("sequence").num());require(sequence<std::numeric_limits<uint64_t>::max(),"pin revision exhausted");(*at)["pinned"]=action==6;(*at)["pinVersion"]=Json::object({{"sequence",sequence+1},{"device",device}});}archive["entries"]=rows;next["archive"]=validateLearning(archive);save(next);}
void ContentStore::mergeRemoteLearning(const Json&archive){auto next=state;next["archive"]=mergeLearning(state.at("archive"),archive);if(next.dump()!=state.dump())save(next);}
void ContentStore::publishLearning(const protocol::VerifiedMembership&m,const GroupIdentity&i,const Key&key,uint64_t now){
 if(!learningEnabled())return;
 auto prepared=prepareLearningDelta(state.at("archive"),m.anchor().group,m.statement().epoch,now,state.has("learningPublication")?&state.at("learningPublication"):nullptr);
 if(!prepared.hasPayload)return;
 const auto fullDigest=sha256(bytes(state.at("archive").dump()));
 auto publication=Json::object({{"checkpoint",prepared.checkpoint},{"digest",base64(Data(fullDigest.begin(),fullDigest.end()))}});
 // Sequence allocation may leave a harmless hole if encryption/persistence
 // fails. The digest baseline itself is saved only beside the durable wire.
 enqueue(bytes(prepared.payload.dump()),1,m,i,key,now,false,nullptr,0,&publication);
}
void ContentStore::sendText(const std::string&text,const protocol::VerifiedMembership&m,const GroupIdentity&i,const Key&key,uint64_t now,bool automatic){validateUtf8(text);require(!text.empty()&&text.size()<=65536&&text.find('\0')==std::string::npos,"shared text bound");enqueue(bytes(text),2,m,i,key,now,automatic);}
void ContentStore::sendCompatibility(const std::string&value,const Id&event,uint64_t expiresAt,const protocol::VerifiedMembership&m,const GroupIdentity&i,const Key&key,uint64_t now){validateUtf8(value);require(!value.empty()&&value.size()<=65536&&value.find('\0')==std::string::npos,"compatibility text bound");require(expiresAt>now&&expiresAt-now<=600,"compatibility original expiry");auto next=state;for(auto p=next["compatibilityQueued"].fields.begin();p!=next["compatibilityQueued"].fields.end();)if(p->second.at("expiresAt").num()<=now)p=next["compatibilityQueued"].fields.erase(p);else ++p;if(next.dump()!=state.dump())save(next);auto hash=sha256(bytes(value));auto digest=base64(Data(hash.begin(),hash.end()));auto id=uuidText(event);if(state.at("compatibilityQueued").has(id)){require(state.at("compatibilityQueued").at(id).at("digest").str()==digest,"compatibility event conflict");return;}enqueue(bytes(value),2,m,i,key,now,true,&event,expiresAt);}
void ContentStore::cancelAutomaticText(){auto next=state;auto&out=next["outgoing"].items;out.erase(std::remove_if(out.begin(),out.end(),[&](const auto&wire){return next.at("automaticOutgoing").has(wire.at("event").str());}),out.end());next["automaticOutgoing"]=Json::object();if(next.dump()!=state.dump())save(next);}
std::vector<Json> ContentStore::pending(uint64_t now){
 auto next=state;bool expiredLearning=false;auto&out=next["outgoing"].items;
 out.erase(std::remove_if(out.begin(),out.end(),[&](const Json&j){if(j.at("expiresAt").num()>now)return false;if(j.at("domain").num()==1)expiredLearning=true;return true;}),out.end());
 for(auto it=next["automaticOutgoing"].fields.begin();it!=next["automaticOutgoing"].fields.end();){if(std::none_of(out.begin(),out.end(),[&](const auto&wire){return wire.at("event").str()==it->first;}))it=next["automaticOutgoing"].fields.erase(it);else ++it;}
 if(next.dump()!=state.dump()){next["publishedDigest"]="";if(expiredLearning)next.fields.erase("learningPublication");save(next);}
 return state.at("outgoing").items;
}
void ContentStore::sent(const Json&wire){auto next=state;auto&out=next["outgoing"].items;auto at=std::find_if(out.begin(),out.end(),[&](const auto&j){return j.at("event").str()==wire.at("event").str();});require(at!=out.end()&&at->dump()==wire.dump(),"outbox ack mismatch");next["automaticOutgoing"].fields.erase(wire.at("event").str());out.erase(at);save(next);}
bool ContentStore::receive(const Json&wire,const protocol::VerifiedMembership&m,const Key&key,uint64_t now){auto envelope=decodeContentEnvelope(wire);require(envelope.sender!=Id{}&&(envelope.domain==1?learningEnabled():clipboardEnabled()),"incoming sharing disabled");require(state.at("group").str()==uuidText(m.anchor().group)&&state.at("epoch").num()==m.statement().epoch,"incoming stale epoch");auto event=uuidText(envelope.event),hash=digest(wire);const auto&receipts=state.at("receipts");if(receipts.has(event)){require(receipts.at(event).str()==hash,"event equivocation");return false;}auto opened=protocol::openOpaquePayload(envelope,key,m.trust(envelope.domain==1?protocol::MembershipDomain::learning:protocol::MembershipDomain::clipboard),ledger(state.at("ledger")),now);auto next=state;if(envelope.domain==1){auto incoming=Json::parse(std::string(opened.payload.begin(),opened.payload.end()),2097152,32,262144);next["archive"]=mergeLearning(state.at("archive"),incoming);}else {auto text=std::string(opened.payload.begin(),opened.payload.end());validateUtf8(text);require(!text.empty()&&text.size()<=65536&&text.find('\0')==std::string::npos,"shared incoming text bound");auto&texts=next["texts"].items;texts.push_back(Json::object({{"event",event},{"sender",uuidText(envelope.sender)},{"issuedAt",envelope.issuedAt},{"text",text}}));while(texts.size()>20||Json::array(texts).dump().size()>262144)texts.erase(texts.begin());}next["ledger"]=encodedLedger(opened.ledger);auto&seen=next["receipts"].fields;if(seen.size()>=512)seen.erase(seen.begin());seen[event]=hash;save(next);return true;}
}
